const ohtDocumentColumns = (columns: { key: string; header: string; width: string; align?: GridColumn['align'] }[]): GridColumn[] =>
  columns.map((column) => ({
    ...column,
    renderCell: column.key === 'action'
      ? editActionCell()
      : staticCell((row) => row[column.key] || ''),
  }));

const editActionCell = (): CellRenderer =>
  (_row, _rowIndex, _updateCell, _disabled) => (
    <Button
      type="button"
      label="Edit"
      className="p-button-sm"
    />
  );

const staticCell =
  (getText: (row: SectionModelRow) => React.ReactNode): CellRenderer =>
  (row, _rowIndex, _updateCell, _disabled, _deleteRow, _rows) => <span style={{ fontWeight: 500 }}>{getText(row)}</span>;

const emptyCell = (): CellRenderer => () => null;

const textInputCell =
  (key: string, placeholder = '', readOnly = false): CellRenderer =>
  (row, _rowIndex, updateCell, disabled, _deleteRow, _rows) => (
    <InputText
      value={row[key] ?? ''}
      placeholder={placeholder}
      disabled={disabled || readOnly}
      readOnly={readOnly}
      onChange={(e: React.ChangeEvent<HTMLInputElement>) => updateCell(key, e.target.value)}
      style={{ width: '100%' }}
      className="p-inputtext-sm"
    />
  );

const dropdownCell =
  (key: string, options: any[], placeholder = ''): CellRenderer =>
  (row: SectionModelRow, _rowIndex, updateCell, disabled, _deleteRow, _rows) => (
    <Dropdown
      value={row[key] ?? null}
      options={options}
      onChange={(e: any) => updateCell(key, e.value)}
      disabled={disabled}
      placeholder={placeholder}
      showClear
      filter
      filterBy="label"
      optionLabel="label"
      optionValue="value"
      className="w-full p-inputtext-sm"
    />
  );

