const roomColumns = (): GridColumn[] => {
  const baseColumns = ohtDocumentColumns([
    { key: 'room', header: 'ROOM', width: '20%' },
    { key: 'model', header: 'MODEL', width: '35%' },
    { key: 'description', header: 'DESCRIPTION', width: '30%' },
    { key: 'action', header: 'ACTION', width: '15%', align: 'center' },
  ]);
  return baseColumns.map((col) => {
    if (col.key === 'model') {
      return {
        ...col,
        renderCell: dropdownCell('model', APARTMENT_ROOM_OPTIONS, 'Select Model'),
      };
    }
    if (col.key === 'description') {
      return {
        ...col,
        renderCell: (row: SectionModelRow, _rowIndex, _updateCell, _disabled) => (
          <span>{APARTMENT_MODEL_DESCRIPTIONS[row.model] || ''}</span>
        ),
      };
    }
    if (col.key === 'action') {
      return {
        ...col,
        renderCell: addModelActionCell(),
      };
    }
    return col;
  });
};

