import React, { useRef, useState } from 'react';
import { useEffect } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import { ESTIMATION_LAYOUT_MODELS, ESTIMATION_LAYOUT_PORTION_MODELS, SECTION_TYPE_ALIASES, getMappedPortionTypes } from '../config';
import { Dropdown } from 'primereact/dropdown';
import { Button } from 'primereact/button';
import PortionTables from '../portions/PortionTables';
import { selectSelectedBlock, selectSelectedProject, setSelectedBlockReducer, setSelectedProjectReducer, useActiveProjectQuery, useAppDispatch, useAppSelector, useBlocksForProjectQuery } from '@igblsln/store';

const Main = () => {
  const [activeTab, setActiveTab] = useState('Measurement');
  const [saveMessage, setSaveMessage] = useState('');

  const [searchParams, setSearchParams] = useSearchParams();
  const portionType = searchParams.get('portion') || '';
  const { section = 'apartment', subsection } = useParams();
  const sectionKey = subsection || section;
  const previousSectionKey = useRef(sectionKey);
  const [portionModelKey, setPortionModelKey] = useState<number>();
  const validPortionSelection = getMappedPortionTypes(sectionKey).includes(portionType);
  const showPortion = validPortionSelection && portionModelKey !== undefined;
  const navigatorPortionType = portionType || getMappedPortionTypes(sectionKey)[0] || '';
  const navigatorPortionModels = ESTIMATION_LAYOUT_PORTION_MODELS.filter(model => model.portionType === navigatorPortionType);
  const portionName = navigatorPortionType === 'column-portion' ? 'Column Bit' : navigatorPortionType.split('-').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  const portionModels = ESTIMATION_LAYOUT_PORTION_MODELS.filter(model => model.portionType === portionType);
  const selectedPortionModel = portionModels.find(model => model.key === portionModelKey);
  useEffect(() => {
    if (previousSectionKey.current !== sectionKey) {
      previousSectionKey.current = sectionKey;
      setPortionModelKey(undefined);
      const next = new URLSearchParams(searchParams);
      next.delete('portion');
      setSearchParams(next, { replace: true });
      return;
    }
    if (portionType && !validPortionSelection) {
      const next = new URLSearchParams(searchParams);
      next.delete('portion');
      setSearchParams(next, { replace: true });
    }
  }, [portionType, sectionKey, validPortionSelection, searchParams, setSearchParams]);
  const sectionName = sectionKey.split('-').map(word => ['oht', 'ots'].includes(word) ? word.toUpperCase() : word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  const modelType = SECTION_TYPE_ALIASES[sectionKey] || sectionKey;
  const models = ESTIMATION_LAYOUT_MODELS.filter(model => model.section_type === modelType);
  const [modelSelection, setModelSelection] = useState<{ section: string; key: number }>();
  const selectedModel = models.find(model => modelSelection?.section === sectionKey && model.key === modelSelection.key) || models[0];
  const selectSectionModel = (key: number) => {
    setModelSelection({ section: sectionKey, key });
    setPortionModelKey(undefined);
    const next = new URLSearchParams(searchParams);
    next.delete('portion');
    setSearchParams(next);
  };
  const [procedureSelection, setProcedureSelection] = useState<{ modelKey: number; name: string }>();
  const modelProcedures = selectedModel?.procedures || [];
  const selectedProcedure = modelProcedures.find(procedure => procedureSelection?.modelKey === selectedModel?.key && procedure.name === procedureSelection?.name) || modelProcedures[0];
  const modelRows = selectedProcedure?.tables[activeTab] || [];
  const [sectionRowValues, setSectionRowValues] = useState<Record<string, { quantity: string; uom: string }>>({});
  const [sectionTableRows, setSectionTableRows] = useState<Record<string, typeof modelRows>>({});
  const sectionTableKey = `${selectedModel?.key || 'none'}-${selectedProcedure?.name || 'none'}-${activeTab}`;
  const activeSectionRows = sectionTableRows[sectionTableKey] || modelRows;
  const updateSectionRow = (index: number, field: 'quantity' | 'uom', value: string) => setSectionTableRows(current => ({
    ...current,
    [sectionTableKey]: activeSectionRows.map((row, rowIndex) => rowIndex === index ? { ...row, [field]: value } : row),
  }));
  const addSectionRow = () => setSectionTableRows(current => ({
    ...current,
    [sectionTableKey]: [...activeSectionRows, activeTab === 'Service'
      ? { name: 'Bar Binding', measurement: 'Area', quantity: '', uom: '', sequence: activeSectionRows.length + 1 }
      : { name: 'Concrete', itemSetType: 'Concrete', measurement: 'Volume', quantity: '', uom: '' }],
  }));
  const deleteSectionRow = (index: number) => setSectionTableRows(current => ({
    ...current,
    [sectionTableKey]: activeSectionRows.filter((_row, rowIndex) => rowIndex !== index).map((row, rowIndex) => ({ ...row, sequence: rowIndex + 1 })),
  }));
  const notifySave = () => {
    setSaveMessage('Saved successfully');
    window.setTimeout(() => setSaveMessage(''), 2500);
  };
  const dispatch = useAppDispatch();
  const selectedProjectKey = useAppSelector(selectSelectedProject);
  const selectedBlockKey = useAppSelector(selectSelectedBlock);
  const { data: projects } = useActiveProjectQuery();
  const { data: blocks } = useBlocksForProjectQuery(
    { projectId: selectedProjectKey },
    { skip: !selectedProjectKey }
  );

  useEffect(() => {
    if (selectedProjectKey === null && projects && projects.length > 0) {
      dispatch(setSelectedProjectReducer(projects[0].key));
    }
  }, [dispatch, projects, selectedProjectKey]);

  useEffect(() => {
    if (selectedProjectKey && blocks && blocks.length > 0 && selectedBlockKey === null) {
      dispatch(setSelectedBlockReducer(blocks[0].key));
    }
  }, [blocks, dispatch, selectedBlockKey, selectedProjectKey]);

  return (
    <div className="estimation-layout-page">
      <style>{`
        .estimation-layout-page{height:100%;padding:0 16px 8px;background:#fff;color:#1f2937;box-sizing:border-box;overflow:auto}
        .estimation-layout-shell{display:grid;grid-template-rows:auto minmax(0,1fr);gap:12px;height:100%;min-height:0}
        .estimation-layout-procedures,.estimation-layout-content{border:1px solid #9ca3af;background:#fff;box-sizing:border-box}
        .estimation-layout-info{background:#fff;box-sizing:border-box}
        .estimation-layout-card{background:#fff;box-sizing:border-box}
        .estimation-layout-panel-title{padding:10px 12px;background:#fce3c9;border-color:#a26360;border-bottom:1px solid #333;font-weight:700}.estimation-layout-save-message{margin-left:8px;color:#397a08;font-weight:700}.estimation-layout-breadcrumb{font-size:13px;color:#64748b;text-align:center;margin:4px 0}
        .estimation-layout-workspace>.estimation-layout-procedures>.estimation-layout-panel-title{border-bottom:1px solid #333333}
        .estimation-layout-main{display:grid;grid-template-rows:auto minmax(0,1fr);min-width:0;min-height:0;border:0;padding:0;box-sizing:border-box}
        .estimation-layout-section,.estimation-layout-portion{grid-template-rows:auto minmax(0,1fr);gap:12px}
        .estimation-layout-card{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:12px 28px;padding:10px 18px}
        .estimation-layout-field{display:flex;align-items:center;gap:8px;width:360px;font-weight:700}
        .estimation-layout-dropdown{width:100%}
        .estimation-layout-info{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:12px 24px;padding:10px 18px;border:1px solid #333333;font-size:14px}
        .estimation-layout-portion>.estimation-layout-info,.estimation-layout-section>.estimation-layout-info{width:calc(100% - 16px);margin:0 auto}
        @media(max-width:640px){.estimation-layout-portion>.estimation-layout-info,.estimation-layout-section>.estimation-layout-info{width:100%;margin:0}}
        .estimation-layout-info-type{display:flex;align-items:center;gap:8px;width:180px;font-weight:700;white-space:nowrap}
        .estimation-layout-section-type-input{width:180px;min-height:30px;padding:6px 10px;border:1px solid #cbd5e1;background:#f8fafc;box-sizing:border-box;font:inherit;font-weight:400}
        .estimation-layout-info-field{display:flex;align-items:center;gap:8px;font-weight:700;min-width:0}
        .estimation-layout-info-field.name-field{width:360px}.estimation-layout-info-field.scope-field{width:180px}
        .estimation-layout-info-field.section-field,.estimation-layout-info-field.portion-field{width:200px}
        .estimation-layout-info-field span:last-child{flex:1;min-height:30px;padding:6px 10px;border:1px solid #cbd5e1;background:#f8fafc;font-weight:400}
        .estimation-layout-actions{display:flex;gap:8px}.estimation-layout-button{min-width:72px;padding:8px 12px;border:0;color:#fff;font:inherit;font-weight:700}.estimation-layout-button.save{background:#4d8b05}.estimation-layout-button.delete{background:#d62f3b}.estimation-layout-button:disabled{opacity:.45;cursor:not-allowed}
        .estimation-layout-workspace{display:grid;grid-template-columns:220px minmax(0,1fr);gap:14px;height:100%;min-height:0;padding:8px;box-sizing:border-box;border:0}
        .estimation-layout-workspace>.estimation-layout-content{border:1px solid #333}
        .estimation-layout-model-navigator{position:relative;display:grid;grid-template-rows:minmax(0,1fr) minmax(0,1fr);gap:12px;min-height:0;overflow:hidden;border:1px solid #333;padding:8px;box-sizing:border-box}
        .estimation-layout-model-navigator>.estimation-layout-procedures{height:auto;min-height:0}
        .estimation-layout-model-navigator>.estimation-layout-procedures:first-child{border-bottom:1px solid #333}
        .estimation-layout-model-navigator>.estimation-layout-procedures:nth-child(2){border-top:1px solid #333}
        .estimation-layout-procedures,.estimation-layout-content{height:100%;min-height:0;border-color:#333333}
        .estimation-layout-procedures{background:#fce3c9;overflow:auto;font-size:calc(1em - 2px)}
        .estimation-layout-model-box{display:grid;grid-template-columns:210px minmax(0,1fr);min-width:0;min-height:0;border:1px solid #333333}
        .estimation-layout-model-box>.estimation-layout-procedures{border:0;border-right:1px solid #333333}
        .estimation-layout-model-box>.estimation-layout-content{border:0}
        .estimation-layout-model-box .estimation-layout-tabs{padding-top:8px;padding-left:14px;box-sizing:border-box}
        .estimation-layout-model-box .estimation-layout-data-table{width:85%}
        @media(max-width:768px){.estimation-layout-model-box .estimation-layout-data-table{width:100%}}
        .estimation-layout-model-box>.estimation-layout-procedures,.estimation-layout-model-box .estimation-layout-panel-title,.estimation-layout-model-box .estimation-layout-procedure-list{background:#fff}
        .estimation-layout-model-box .estimation-layout-procedure-list{display:flex;flex-direction:column;gap:8px;padding:0 10px 10px}
        .estimation-layout-model-box>.estimation-layout-procedures>.estimation-layout-panel-title{text-align:center;border-bottom:1px solid #333333;margin-bottom:10px}
        .estimation-layout-model-box .estimation-layout-procedure-button{border:1px solid #9ca3af;background:#fff;padding:10px 12px}
        .estimation-layout-model-box .estimation-layout-procedure-button:hover{background:#f3f4f6}
        .estimation-layout-model-box .estimation-layout-procedure-button.active{background:#827f7f;color:#fff;font-weight:700}
        .estimation-layout-content{display:grid;grid-template-rows:auto minmax(0,1fr);min-width:0;background:#fff!important}.estimation-layout-tabs{display:flex;gap:4px;background:#fff!important}
        .estimation-layout-tab{padding:10px 18px;border:1px solid #9ca3af;background:#fff;font-weight:700;cursor:pointer}.estimation-layout-tab.active{background:#827f7f;color:#fff}
        .estimation-layout-procedure-list{background:#fce3c9}
        .estimation-layout-procedure-button{display:block;width:100%;padding:9px 12px;border:0;border-bottom:1px solid #cbd5e1;background:transparent;text-align:left;font:inherit;cursor:pointer}.estimation-layout-procedure-button.active{background:#f6c38f;font-weight:700}
        .estimation-layout-data{min-height:0;overflow:auto;padding:14px;background:#fff}.estimation-layout-data-title{margin-bottom:10px;font-weight:700}.estimation-layout-data-table{width:100%;border-collapse:collapse}.estimation-layout-data-table th,.estimation-layout-data-table td{padding:8px;border:1px solid #9ca3af;text-align:left}.estimation-layout-data-table th{background:#827f7f;color:#fff}
        .estimation-layout-empty-state{display:flex;align-items:center;justify-content:center;min-height:180px;padding:24px;color:#64748b;text-align:center;font-weight:600}
        .estimation-layout-data-table .section-quantity-cell{display:flex;align-items:center;gap:6px;min-width:150px}.estimation-layout-data-table .section-quantity-input{width:66px;min-width:0;height:28px;padding:4px 8px;border:1px solid #cbd5e1;border-radius:4px;box-sizing:border-box}.estimation-layout-data-table .section-uom-select{height:28px;min-width:78px;padding:2px 6px;border:1px solid #cbd5e1;border-radius:4px;background:#fff}
        .estimation-layout-data-table.measurement-table,.estimation-layout-data-table.item-set-table,.estimation-layout-data-table.service-table{width:82%;margin:0}.estimation-layout-data-table .section-action-cell{text-align:center}.estimation-layout-data-table .section-action-button{width:34px;min-width:34px;height:26px;padding:0;border:1px solid #ef4444;background:#fff;color:#ef4444;font-size:16px;line-height:1}.estimation-layout-data-table .section-action-button.add{border-color:#4d8b05;color:#4d8b05}
        .estimation-layout-data-table.item-set-table tbody td,.estimation-layout-data-table.service-table tbody td{height:36px;padding:5px 8px;box-sizing:border-box;vertical-align:middle}
        .estimation-layout-data-table.item-set-table td.section-quantity-cell,.estimation-layout-data-table.service-table td.section-quantity-cell{display:table-cell;white-space:nowrap;vertical-align:middle}.estimation-layout-data-table.item-set-table td.section-quantity-cell .section-quantity-input,.estimation-layout-data-table.item-set-table td.section-quantity-cell .section-uom-select,.estimation-layout-data-table.service-table td.section-quantity-cell .section-quantity-input,.estimation-layout-data-table.service-table td.section-quantity-cell .section-uom-select{display:inline-block;vertical-align:middle}
        .estimation-layout-data-table.item-set-table .section-quantity-input,.estimation-layout-data-table.item-set-table .section-uom-select,.estimation-layout-data-table.service-table .section-quantity-input,.estimation-layout-data-table.service-table .section-uom-select{height:26px}
        .estimation-layout-data-table.measurement-table th,.estimation-layout-data-table.measurement-table td,.estimation-layout-data-table.item-set-table th,.estimation-layout-data-table.item-set-table td,.estimation-layout-data-table.service-table th,.estimation-layout-data-table.service-table td{text-align:center}
        @media(max-width:640px){.estimation-layout-card,.estimation-layout-info{grid-template-columns:1fr;flex-direction:column;align-items:stretch;gap:10px}.estimation-layout-field{min-width:0;width:100%}.estimation-layout-workspace{grid-template-columns:1fr}.estimation-layout-procedures{min-height:0}}
      `}</style>
      <div className="estimation-layout-shell">
          <section className="estimation-layout-card" aria-label="Project and block selection">
            <div className="estimation-layout-field"><label htmlFor="estimation-project">Project:</label><Dropdown id="estimation-project" className="estimation-layout-dropdown" value={selectedProjectKey} options={projects || []} optionLabel="name" optionValue="key" placeholder="Select Project" showClear filter onChange={(event) => { dispatch(setSelectedProjectReducer(event.value)); dispatch(setSelectedBlockReducer(null)); }} /></div>
            <div className="estimation-layout-field"><label htmlFor="estimation-block">Block:</label><Dropdown id="estimation-block" className="estimation-layout-dropdown" value={selectedBlockKey} options={blocks || []} optionLabel="descr" optionValue="key" placeholder="Select Block" showClear filter disabled={!selectedProjectKey} onChange={(event) => dispatch(setSelectedBlockReducer(event.value))} /></div>
          </section>
        {!showPortion ? <section className="estimation-layout-main estimation-layout-section" aria-label="Section model workspace">
          <section className="estimation-layout-info" aria-label="Section information">
            <div className="estimation-layout-info-type"><input className="estimation-layout-section-type-input" value={sectionName} readOnly /></div>
            <div className="estimation-layout-info-field name-field"><span>Name -</span><span>{selectedModel?.name || ''}</span></div>
            <div className="estimation-layout-info-field scope-field"><span>Scope -</span><span>{selectedModel?.scope || ''}</span></div>
            <div className="estimation-layout-actions"><button className="estimation-layout-button save" type="button" disabled={!selectedModel} onClick={notifySave} title="Save section model">Save</button><button className="estimation-layout-button delete" type="button" disabled={!selectedModel} onClick={() => window.confirm('Delete this section model?')} title="Delete section model">Delete</button>{saveMessage && <span className="estimation-layout-save-message">{saveMessage}</span>}</div>
          </section>
          <section className="estimation-layout-workspace" aria-label="Section models and estimation tabs">
            <div className="estimation-layout-model-navigator">
              <div className="estimation-layout-procedures">
                <div className="estimation-layout-panel-title">{sectionName} Models</div>
                <div className="estimation-layout-procedure-list">
                  {models.length === 0 ? <div className="estimation-layout-panel-title">No models available for {sectionName}.</div>
                    : models.map(model => <button key={model.key} type="button" aria-pressed={!showPortion && selectedModel === model} className={`estimation-layout-procedure-button${!showPortion && selectedModel === model ? ' active' : ''}`} onClick={() => selectSectionModel(model.key)}>{model.name}</button>)}
                </div>
              </div>
              <div key={navigatorPortionType} className="estimation-layout-procedures estimation-layout-portion-model-navigator">
                <div className="estimation-layout-panel-title">Portion Models</div>
                <div className="estimation-layout-procedure-list">
                  {navigatorPortionModels.length === 0 ? <div className="estimation-layout-panel-title">No portion models available.</div>
                    : navigatorPortionModels.map(model => <button key={model.key} type="button" aria-pressed={selectedPortionModel === model} className={`estimation-layout-procedure-button${selectedPortionModel === model ? ' active' : ''}`} onClick={() => { setPortionModelKey(model.key); const next = new URLSearchParams(searchParams); next.set('portion', navigatorPortionType); setSearchParams(next); }}>{model.name}</button>)}
                </div>
              </div>
            </div>
            <div className="estimation-layout-model-box">
              <div className="estimation-layout-procedures" aria-label="Selected model procedures">
                <div className="estimation-layout-panel-title">Procedures</div>
                <div className="estimation-layout-procedure-list">
                  {modelProcedures.length === 0 ? <div className="estimation-layout-panel-title">No procedures configured.</div>
                    : modelProcedures.map(procedure => <button key={procedure.name} type="button" aria-pressed={selectedProcedure === procedure} className={`estimation-layout-procedure-button${selectedProcedure === procedure ? ' active' : ''}`} onClick={() => selectedModel && setProcedureSelection({ modelKey: selectedModel.key, name: procedure.name })}>{procedure.name}</button>)}
                </div>
              </div>
              <div className="estimation-layout-content">
              <div className="estimation-layout-tabs" role="tablist" aria-label="Section model tables">
                {['Measurement', 'Item Set', 'Service'].map(tab => <button key={tab} type="button" role="tab" aria-selected={activeTab === tab} className={`estimation-layout-tab${activeTab === tab ? ' active' : ''}`} onClick={() => setActiveTab(tab)}>{tab}</button>)}
              </div>
              <div className="estimation-layout-data" aria-label={`${selectedModel?.name || sectionName} ${selectedProcedure?.name || ''} ${activeTab} data`}>
                {/* <div className="estimation-layout-data-title">{selectedModel?.name || sectionName}{selectedProcedure ? ` - ${selectedProcedure.name}` : ''} - {activeTab}</div> */}
                {activeTab === 'Measurement' ? <table className="estimation-layout-data-table measurement-table">
                  <colgroup><col style={{ width: '35%' }} /><col style={{ width: '25%' }} /><col style={{ width: '20%' }} /><col style={{ width: '20%' }} /></colgroup>
                  <thead><tr><th>Name</th><th>Measurement</th><th>Quantity</th><th aria-label="Empty column"></th></tr></thead>
                  <tbody>{modelRows.length > 0 ? modelRows.map((row, index) => <tr key={index}><td>{row.name}</td><td>{row.measurement ?? '-'}</td><td className="section-quantity-cell"><input className="section-quantity-input" type="text" value={sectionRowValues[`Measurement-${index}`]?.quantity ?? (row.quantity ?? '')} onChange={event => setSectionRowValues(current => ({ ...current, [`Measurement-${index}`]: { quantity: event.target.value, uom: current[`Measurement-${index}`]?.uom ?? row.uom ?? '' } }))} /><select className="section-uom-select" value={sectionRowValues[`Measurement-${index}`]?.uom ?? (row.uom ?? '')} onChange={event => setSectionRowValues(current => ({ ...current, [`Measurement-${index}`]: { quantity: current[`Measurement-${index}`]?.quantity ?? String(row.quantity ?? ''), uom: event.target.value } }))}><option value="">UOM</option><option value="m">m</option><option value="Nos">Nos</option><option value="Sq.Ft">Sq.Ft</option><option value="ft">ft</option></select></td><td aria-hidden="true"></td></tr>) : <tr><td colSpan={4}>{!selectedModel ? 'No section model selected.' : !selectedProcedure ? 'No procedures configured for this model.' : 'No measurement data available for this procedure.'}</td></tr>}</tbody>
                </table> : activeTab === 'Item Set' ? <table className="estimation-layout-data-table item-set-table">
                  <colgroup><col style={{ width: '15%' }} /><col style={{ width: '18%' }} /><col style={{ width: '15%' }} /><col style={{ width: '18%' }} /><col style={{ width: '8%' }} /><col style={{ width: '8%' }} /></colgroup>
                  <thead><tr><th>Item Set Type</th><th>Item Set Name</th><th>Measurement</th><th>Quantity</th><th>Delete</th><th>Add</th></tr></thead>
                  <tbody>{activeSectionRows.length > 0 ? activeSectionRows.map((row, index) => <tr key={index}><td>{row.itemSetType || '-'}</td><td>{row.name}</td><td>{row.measurement ?? '-'}</td><td className="section-quantity-cell"><input className="section-quantity-input" type="text" value={row.quantity ?? ''} onChange={event => updateSectionRow(index, 'quantity', event.target.value)} /><select className="section-uom-select" value={row.uom ?? ''} onChange={event => updateSectionRow(index, 'uom', event.target.value)}><option value="">Select</option><option value="m">m</option><option value="Nos">Nos</option><option value="Sq.Ft">Sq.Ft</option><option value="ft">ft</option></select></td><td className="section-action-cell"><Button type="button" icon="pi pi-trash" className="p-button-sm p-button-outlined p-button-danger section6-procedure-delete" aria-label="Delete item set" onClick={() => deleteSectionRow(index)} /></td>{index === 0 && <td className="section-action-cell" rowSpan={activeSectionRows.length || 1}><Button type="button" icon="pi pi-plus" className="p-button-sm p-button-outlined p-button-success section6-procedure-add" aria-label="Add item set" onClick={addSectionRow} /></td>}</tr>) : <tr><td colSpan={6}>No item set data available for this procedure.</td></tr>}</tbody>
                </table> : <table className="estimation-layout-data-table service-table">
                  <colgroup><col style={{ width: '8%' }} /><col style={{ width: '25%' }} /><col style={{ width: '15%' }} /><col style={{ width: '18%' }} /><col style={{ width: '8%' }} /><col style={{ width: '8%' }} /></colgroup>
                  <thead><tr><th>S.No</th><th>Service Name</th><th>Measurement</th><th>Quantity</th><th>Delete</th><th>Add</th></tr></thead>
                  <tbody>{activeSectionRows.length > 0 ? activeSectionRows.map((row, index) => <tr key={index}><td>{row.sequence || index + 1}</td><td>{row.name}</td><td>{row.measurement ?? '-'}</td><td className="section-quantity-cell"><input className="section-quantity-input" type="text" value={row.quantity ?? ''} onChange={event => updateSectionRow(index, 'quantity', event.target.value)} /><select className="section-uom-select" value={row.uom ?? ''} onChange={event => updateSectionRow(index, 'uom', event.target.value)}><option value="">Select</option><option value="m">m</option><option value="Nos">Nos</option><option value="Sq.Ft">Sq.Ft</option><option value="ft">ft</option></select></td><td className="section-action-cell"><Button type="button" icon="pi pi-trash" className="p-button-sm p-button-outlined p-button-danger section6-procedure-delete" aria-label="Delete service" onClick={() => deleteSectionRow(index)} /></td>{index === 0 && <td className="section-action-cell" rowSpan={activeSectionRows.length || 1}><Button type="button" icon="pi pi-plus" className="p-button-sm p-button-outlined p-button-success section6-procedure-add" aria-label="Add service" onClick={addSectionRow} /></td>}</tr>) : <tr><td colSpan={6}>No service data available for this procedure.</td></tr>}</tbody>
                </table>}
              </div>
              </div>
            </div>
          </section>
        </section> : <section className="estimation-layout-main estimation-layout-portion" aria-label="Portion model workspace">
          <section className="estimation-layout-info" aria-label="Portion information">
            <div className="estimation-layout-info-field section-field"><span>Section</span><span>{sectionName}</span></div>
            <div className="estimation-layout-info-field portion-field"><span>Portion</span><span>{portionName}</span></div>
            <div className="estimation-layout-info-field name-field"><span>Name -</span><span>{selectedPortionModel?.name || ''}</span></div>
            <div className="estimation-layout-actions"><button className="estimation-layout-button save" type="button" disabled={!selectedPortionModel} onClick={notifySave} title="Save portion model">Save</button><button className="estimation-layout-button delete" type="button" disabled={!selectedPortionModel} onClick={() => window.confirm('Delete this portion model?')} title="Delete portion model">Delete</button>{saveMessage && <span className="estimation-layout-save-message">{saveMessage}</span>}</div>
          </section>
          <section className="estimation-layout-workspace" aria-label="Portion models and tables">
            <div className="estimation-layout-model-navigator">
              <div className="estimation-layout-procedures">
                <div className="estimation-layout-panel-title">{sectionName} Models</div>
                <div className="estimation-layout-procedure-list">
                  {models.length === 0 ? <div className="estimation-layout-panel-title">No models available for {sectionName}.</div>
                    : models.map(model => <button key={model.key} type="button" aria-pressed={!showPortion && selectedModel === model} className={`estimation-layout-procedure-button${!showPortion && selectedModel === model ? ' active' : ''}`} onClick={() => selectSectionModel(model.key)}>{model.name}</button>)}
                </div>
              </div>
              <div key={portionType} className="estimation-layout-procedures">
                <div className="estimation-layout-panel-title">Portion Models</div>
                <div className="estimation-layout-procedure-list">
                  {portionModels.map(model => <button key={model.key} type="button" aria-pressed={selectedPortionModel === model} className={`estimation-layout-procedure-button${selectedPortionModel === model ? ' active' : ''}`} onClick={() => setPortionModelKey(model.key)}>{model.name}</button>)}
                  {portionModels.length === 0 && <div className="estimation-layout-panel-title">No portion models available.</div>}
                </div>
              </div>
            </div>
            <div className="estimation-layout-content" style={{ display: 'block', overflow: 'auto' }}>
              {selectedPortionModel ? <PortionTables key={selectedPortionModel.key} portionType={portionType} modelName={selectedPortionModel.name} /> : <div className="estimation-layout-empty-state">Select a portion model to view its data.</div>}
            </div>
          </section>
        </section>}
      </div>
    </div>
  );
};

export default Main;


