import React, { useMemo } from 'react';
import { Navigate, Route, Routes, useLocation, useSearchParams } from 'react-router-dom';
import { getMappedPortionTypes } from '../config';
import { ModuleLayout, NoMatch } from '@igblsln/control';
import routes, { portionItems } from './routes';
import MainPage from '../pages/Main';
import { selectSelectedBlock, selectSelectedProject, useAppSelector, useBlocksForProjectQuery } from '@igblsln/store';

const portionKeyForLabel = (label: string) => label === 'Column Bit' ? 'column-portion' : label.toLowerCase().replace(/\s+/g, '-');

const markActiveSectionItems = (items: any[], pathname: string): any[] => items.map(item => {
  const slug = typeof item.label === 'string' ? item.label.toLowerCase().replace(/\s+/g, '-') : '';
  const active = (item.label === 'Apartment' && pathname.endsWith('/layout')) || (slug && pathname.includes(`/${slug}`));
  return {
    ...item,
    className: `${item.className || ''}${active ? ' p-menuitem-active' : ''}`,
    items: item.items ? markActiveSectionItems(item.items, pathname) : item.items,
  };
});

const Main = () => {
  const { pathname } = useLocation();
  const pathParts = pathname.split('/').filter(Boolean);
  const sectionKey = pathParts[pathParts.length - 1] === 'layout' ? 'apartment' : pathParts[pathParts.length - 1];
  const mappedPortions = useMemo(() => getMappedPortionTypes(sectionKey), [sectionKey]);
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedProject = useAppSelector(selectSelectedProject);
  const selectedBlock = useAppSelector(selectSelectedBlock);
  const { data: blocks } = useBlocksForProjectQuery(
    { projectId: selectedProject },
    { skip: !selectedProject }
  );
  const blockName = blocks?.find(block => block.key === selectedBlock)?.descr || 'Select Block';
  const availableBlocks: Array<{ descr: string }> = useMemo(() => blocks && blocks.length > 0
    ? blocks.map(block => ({ descr: block.descr || blockName }))
    : [{ descr: blockName }], [blocks, blockName]);
  const sectionNavigation = useMemo(() => routes.map(group => ({
    ...group,
    items: availableBlocks.reduce<any[]>((items, block) => items.concat(group.items.map(mainItem => ({
      ...mainItem,
      label: `Block (${block.descr || blockName})`,
      items: markActiveSectionItems(mainItem.items || [], pathname),
    }))), []),
  })), [availableBlocks, blockName, pathname]);
  const portionNavigation = useMemo(() => portionItems.map(group => ({
    ...group,
    items: mappedPortions.length === 0 ? [{ label: 'No portions mapped', disabled: true }] : group.items.filter(item => mappedPortions.includes(portionKeyForLabel(item.label))).map((item, index) => ({
      ...item,
      className: `${(item as any).className || ''}${searchParams.get('portion') === portionKeyForLabel(item.label) || (!searchParams.get('portion') && index === 0) ? ' p-menuitem-active' : ''}`,
      command: () => {
        const next = new URLSearchParams(searchParams);
        next.set('portion', portionKeyForLabel(item.label));
        setSearchParams(next);
      },
    })),
  })), [mappedPortions, searchParams, setSearchParams]);

  return (
  <>
  <Routes>
    <Route path="/" element={<ModuleLayout navItems={sectionNavigation} panelMenu splitNavigation flushContent navigationSize={14} secondaryNavItems={portionNavigation} />}>
      <Route index element={<Navigate to="layout" replace />} />
      <Route path="layout" element={<MainPage />} />
      <Route path="layout/:section" element={<MainPage />} />
      <Route path="layout/:section/:subsection" element={<MainPage />} />
      <Route path="*" element={<NoMatch relative />} />
    </Route>
  </Routes>
  </>
);
};

export default Main;
